INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(371085, 30592, 9504, '<td valign="top">You shouldh ave cropped him. There is too much dark space which makes him less powerful.</td>', 'You shouldh ave cropped him. There is too much dark space which makes him less powerful.', '2003-07-30 13:45:21.000000', NULL, 1),
(371086, 30883, 10219, '<td valign="top">It looks like you took a branch from a weed, laid it on the ground and took a picture of it......... 2</td>', 'It looks like you took a branch from a weed, laid it on the ground and took a picture of it......... 2', '2003-07-30 13:45:23.000000', NULL, 1),
(371087, 30945, 3087, '<td valign="top">A lovely image... I hope you don''t get too many comments dismissing this just because something similar has been done before. Whilst I can see similarities to Setzler''s Foliage entry, which itself reflects work of earlier photographers, I think this is a unique take on the theme. I love the diagonal vein across the image. Does seem somewhat pixelated?</td>', 'A lovely image... I hope you don''t get too many comments dismissing this just because something similar has been done before. Whilst I can see similarities to Setzler''s Foliage entry, which itself reflects work of earlier photographers, I think this is a unique take on the theme. I love the diagonal vein across the image. Does seem somewhat pixelated?', '2003-07-30 13:45:36.000000', NULL, 1),
(371089, 30230, 9504, '<td valign="top">Very nice!  The wings look so crisp.</td>', 'Very nice!  The wings look so crisp.', '2003-07-30 13:46:41.000000', NULL, 1),
(371090, 31012, 3087, '<td valign="top">Beautiful and vibrant colour, great composition, it''s like he''s on a stage with a soft rug beneath his feet and a yellow curtain behind him. I like the diagonal of his body - aids composition.</td>', 'Beautiful and vibrant colour, great composition, it''s like he''s on a stage with a soft rug beneath his feet and a yellow curtain behind him. I like the diagonal of his body - aids composition.', '2003-07-30 13:46:42.000000', NULL, 1),
(371091, 31018, 10219, '<td valign="top">I like the angle and perspective that you chose here, I like that it is not a color photograph anymore, gives it an old feel and makes it warm and home like... 8</td>', 'I like the angle and perspective that you chose here, I like that it is not a color photograph anymore, gives it an old feel and makes it warm and home like... 8', '2003-07-30 13:46:50.000000', NULL, 1),
(371092, 30679, 9734, '<td valign="top">surely that is photography now? maize in this time only maturing.</td>', 'surely that is photography now? maize in this time only maturing.', '2003-07-30 13:47:41.000000', NULL, 1),
(371093, 31244, 10219, '<td valign="top">I am so amazed that you found such a small snake......  I like it because it is an animal on a flower, that ISN''T an INSECT!!!!!!!   7</td>', 'I am so amazed that you found such a small snake......  I like it because it is an animal on a flower, that ISN''T an INSECT!!!!!!!   7', '2003-07-30 13:47:56.000000', NULL, 1),
(371094, 31225, 3087, '<td valign="top">Quirky and colourful I like this a lot, though I think I''d prefer to exclude the bottom area and have the large complete stone as the lower edge of the image.</td>', 'Quirky and colourful I like this a lot, though I think I''d prefer to exclude the bottom area and have the large complete stone as the lower edge of the image.', '2003-07-30 13:48:13.000000', NULL, 1),
(371095, 31168, 10219, '<td valign="top">and it looks like he caught a fish!!!!!!!!  What a great landscape, wish I was there....... POINTS for Originality and taking a risk!!!   8</td>', 'and it looks like he caught a fish!!!!!!!!  What a great landscape, wish I was there....... POINTS for Originality and taking a risk!!!   8', '2003-07-30 13:49:01.000000', NULL, 1),
