(371451, 30815, 9690, '<td valign="top">very cute.. great idea and well done</td>', 'very cute.. great idea and well done', '2003-07-30 18:05:31.000000', NULL, 1),
(371452, 31131, 10328, '<td valign="top">Excellent shot. You may consider bringing the camera closer to the ground next time, and capturing more of the trees in the background to round out the shot.</td>', 'Excellent shot. You may consider bringing the camera closer to the ground next time, and capturing more of the trees in the background to round out the shot.', '2003-07-30 18:06:24.000000', NULL, 1),
(371453, 30617, 10328, '<td valign="top">Out of focus. Beautiful wings, enjoyed seeing the detail on them.</td>', 'Out of focus. Beautiful wings, enjoyed seeing the detail on them.', '2003-07-30 18:08:01.000000', NULL, 1),
