(371463, 30943, 10328, '<td valign="top">Great contrast of color.</td>', 'Great contrast of color.', '2003-07-30 18:16:09.000000', NULL, 1),
(371464, 31083, 10328, '<td valign="top">Fantastic! Great focus.</td>', 'Fantastic! Great focus.', '2003-07-30 18:17:13.000000', NULL, 1),
