(371467, 31075, 10328, '<td valign="top">It''s got good focus, it''s just too small/far away to tell what it is.</td>', 'It''s got good focus, it''s just too small/far away to tell what it is.', '2003-07-30 18:19:25.000000', NULL, 1),
(371468, 31009, 10328, '<td valign="top">Yikes!! - Great work!</td>', 'Yikes!! - Great work!', '2003-07-30 18:19:55.000000', NULL, 1),
