(375190, 30112, 10403, '<td valign="top">Great composition, the leaf of the plant leads you to the bird''s eye and you suddenly realise whats hiding! 7</td>', 'Great composition, the leaf of the plant leads you to the bird''s eye and you suddenly realise whats hiding! 7', '2003-08-03 13:25:52.000000', NULL, 1),
(375191, 31059, 10403, '<td valign="top">Focus is wonderful. 8</td>', 'Focus is wonderful. 8', '2003-08-03 13:26:26.000000', NULL, 1),
