(375333, 30993, 3290, '<td valign="top">:-)</td>', ':-)', '2003-08-03 17:50:41.000000', NULL, 1),
(375334, 31235, 3290, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2003-08-03 17:52:49.000000', NULL, 1),
(375336, 31186, 3290, '<td valign="top">Pretty subject, but a little soft and grainy.</td>', 'Pretty subject, but a little soft and grainy.', '2003-08-03 17:53:21.000000', NULL, 1),
