(377155, 31083, 10799, '<td valign="top">Crisp and clear.</td>', 'Crisp and clear.', '2003-08-05 11:07:07.000000', NULL, 1),
(377156, 31170, 1202, '<td valign="top">I call these the mile a minute bug.  Just about the time you push the shutter they take off.   This is good with nice focus and use of depth of field.   8</td>', 'I call these the mile a minute bug.  Just about the time you push the shutter they take off.   This is good with nice focus and use of depth of field.   8', '2003-08-05 11:07:43.000000', NULL, 1),
