(377707, 30583, 8159, '<td valign="top">I this would have been better if it wasn''t cropped so tight and showed more clearly that the watermelon was still on the vine and "growing in the garden". The tight cropping on the hands loses a lot of the "garden" character. Otherwise, nice shot.</td>', 'I this would have been better if it wasn''t cropped so tight and showed more clearly that the watermelon was still on the vine and "growing in the garden". The tight cropping on the hands loses a lot of the "garden" character. Otherwise, nice shot.', '2003-08-05 23:10:52.000000', NULL, 1),
(377713, 31224, 7969, '<td valign="top">great colors, sharp and clear.  Not a dramatic shot but very pleasing.</td>', 'great colors, sharp and clear.  Not a dramatic shot but very pleasing.', '2003-08-05 23:17:27.000000', NULL, 1),
(377717, 30593, 7969, '<td valign="top">Fabulous shot, technically excellent, great to look up close at an interesting critter.</td>', 'Fabulous shot, technically excellent, great to look up close at an interesting critter.', '2003-08-05 23:19:36.000000', NULL, 1),
